{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret er generisk og savner kernen i vejledningen: sygehistorik, seneste journalnotater og epikriser. Det nævner handicapid-kort og skolepædagogiske vurderinger uden støtte i kilderne. Det angiver ikke, at de seneste oplysninger kan være ældre, og det nævner ikke, at en personlig redegørelse supplerer men ikke erstatter lægefaglig dokumentation. Der er ingen egentlig modsigelse af kilderne, men manglerne og tilføjelserne er væsentlige."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de kritiske elementer mangler: sygehistorik og de seneste journalnotater, udrednings- og behandlingsforløb, epikriser og journalnotater som eksempler, støtteforanstaltninger og skånehensyn som supplement samt den personlige redegørelse. Lægeerklæring og medicinsk dokumentation er kun delvis og generisk dækning."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er rettet mod spørgsmålet om hvilken dokumentation der kan sendes med, og giver en liste over dokumenttyper. Indholdet er upræcist, men det er ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om kilder understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer handicapid-kort og skolepædagogiske vurderinger som dokumentation uden støtte i kildematerialet. Det tilføjer også en anbefaling om at søge råd hos en læge før indsendelse og om at få dokumenterne 'korrekt udfyldt', som heller ikke har støtte i kilderne."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "De påkrævede forbehold mangler. Svaret siger ikke, at de seneste foreliggende oplysninger kan være ældre, at eksemplerne ikke er kumulative krav, eller at en personlig redegørelse kun supplerer og ikke ophæver det lægefaglige dokumentationsminimum."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det er en liste over mulige dokumenter med en afsluttende anbefaling og indeholder ingen selvmodsigelser. Konklusionen følger af de trin, der er givet."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan' om dokumentation og gør ikke noget til et absolut krav. Det formulerer ikke minimumskravet om journaler fra § 37, stk. 3, men det gør heller ikke valgfrie elementer obligatoriske."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "no",
      "reason": "Svaret nævner ikke sygehistorik, seneste journalnotater, den personlige redegørelse eller eksempler på medfødte funktionsnedsættelser. Det behandler heller ikke, at nyere dokumentation ofte mangler."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret nævner lægeerklæring og medicinsk dokumentation fra hospital og speciallæger, hvilket nærmer sig lægefaglige oplysninger. Det nævner ikke epikriser, journalnoter, udrednings- og behandlingsforløb, støtteafgørelser, skånehensyn eller den personlige redegørelse som alternativ, når dokumentation mangler."
    }
  },
  "overall_notes": "Svaret er generisk og uden kildehenvisninger. Det mangler vejledningens kerneelementer og de påkrævede forbehold, og det tilføjer ikke-understøttede dokumenttyper som handicapid-kort og skolepædagogiske vurderinger."
}

